nge payment.</div>';}elseif(dm_is_admin($u)&&$b['status']!=='paid'){echo '<h2>Payment review</h2>';if($b['status']==='pending'){dm_begin_form('verify_payment','bill',['id'=>$b['id']]);dm_hidden('id',$b['id']);echo '<p>Confirm the transfer in your GCash account before approving.</p>';dm_submit_button('Verify and mark paid');echo '</form><hr>';dm_begin_form('reject_payment','bill',['id'=>$b['id']]);dm_hidden('id',$b['id']);dm_field('rejection_reason','Reason for rejection','','text','required');dm_submit_button('Reject receipt','outline-danger');echo '</form><hr>';}echo '<details><summary>Record a cash payment</summary>';dm_begin_form('cash_payment','bill',['id'=>$b['id']]);dm_hidden('id',$b['id']);echo '<p>Only confirm after receiving the full amount.</p>';dm_submit_button('Confirm cash received');echo '</form></details>';}else echo '<h2>'.($b['status']==='paid'?'Payment complete':'Awaiting verification').'</h2><p>'.($b['status']==='paid'?'Thank you. Your payment has been recorded.':'Your administrator will review the receipt.').'</p>';echo '</section></div></div>';
